"""Frozen-release checks: real parent-first journey and SIEM without a sports profile.
Synthetic family records only. No remote writes or connector activation.
"""
import importlib.util,unittest,json,base64
from pathlib import Path
spec=importlib.util.spec_from_file_location('baseline',Path(__file__).with_name('qa-20261112.py'));base=importlib.util.module_from_spec(spec);spec.loader.exec_module(base)
OUT=Path('var/release-candidate');OUT.mkdir(parents=True,exist_ok=True)
class ReleaseCandidate(unittest.TestCase):
 setUpClass=classmethod(base.Remediation.setUpClass.__func__)
 tearDownClass=classmethod(base.Remediation.tearDownClass.__func__)
 tearDown=base.Remediation.tearDown
 state=base.Remediation.state
 section=base.Remediation.section
 add=base.Remediation.add
 def setUp(self):
  self.context=self.browser.new_context(viewport={'width':810,'height':1080});self.page=self.context.new_page();self.errors=[];self.writes=[];self.page.on('pageerror',lambda e:self.errors.append(str(e)));self.page.on('request',lambda r:self.writes.append(r.url) if r.method not in ['GET','HEAD'] else None)
 def family(self):return self.page.evaluate('JSON.parse(localStorage.getItem("arenaPathway.siem.v1"))')
 def test_01_parent_first_journey_and_module_independence(self):
  p=self.page;p.goto(base.BASE+'/siem/setup');p.locator('#parent-add input[name=nickname]').fill('Release QA Parent');p.get_by_role('button',name='Add parent participant',exact=True).click();p.wait_for_function('()=>JSON.parse(localStorage.getItem("arenaPathway.siem.v1")).athletes.some(a=>a.type==="parent")');parent=self.family()['athletes'][0]['id']
  p.goto(base.BASE+'/my-pathway?view=family');p.get_by_role('link',name='+ Add athlete',exact=True).click();p.wait_for_selector('#athlete-journey');p.get_by_role('button',name='Enter basics instead',exact=True).click();p.wait_for_selector('#athlete-basics:not([disabled])');p.locator('#nickname').fill('Release QA Athlete');p.locator('#sport').select_option('lacrosse');p.locator('#guardian').check()
  # Use an actual catalog choice when present, never invent a directory organization.
  choices=p.locator('#club-team').get_attribute('list');p.wait_for_function('(id)=>document.getElementById(id)?.options.length>0',arg=choices);club=p.locator('#'+choices+' option').first.get_attribute('value');p.locator('#club-team').fill(club);p.locator('#position').fill('Midfield');p.get_by_role('button',name='Save athlete profile').click();p.wait_for_selector('#show-tryouts');self.athlete=self.state()['active'];athlete=self.athlete
  self.assertEqual(len(self.state()['profiles']),1);self.assertEqual(self.state()['profiles'][0]['clubTeam'],club);self.assertNotIn('recruiting',self.state()['profiles'][0]['modules'])
  self.add(repeat=True);self.assertEqual(p.locator('#schedule-list article').count(),3);sid=self.state()['profiles'][0]['plans'][0]['id'];p.get_by_role('button',name='Edit this occurrence',exact=True).first.click();p.locator('#plan-title').fill('Release moved practice');p.locator('#plan-start').fill('2026-11-17');p.locator('#plan-end').fill('2026-11-17');p.get_by_role('button',name='Save this occurrence',exact=True).click();self.assertIn('Release moved practice',p.locator('#schedule-list').inner_text());self.assertEqual(self.state()['profiles'][0]['plans'][0]['id'],sid)
  self.add(kind='tournament');event=self.state()['profiles'][0]['plans'][1]['id'];p.locator('#schedule-list article').filter(has_text='QA tournament').get_by_role('button',name='Log stats',exact=True).click();self.assertEqual(p.locator('#record-event').input_value(),event);p.locator('#metric-Goals').fill('2');p.locator('#record-achievement').fill('Release QA result');p.get_by_role('button',name='Save game / meet record',exact=True).click();p.wait_for_selector('#stats .record');self.assertEqual(self.state()['profiles'][0]['records'][0]['eventRef'],event)
  self.section('Media');p.locator('#media-upload').set_input_files({'name':'rc-fixture.png','mimeType':'image/png','buffer':base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+a8RQAAAAASUVORK5CYII=')});p.locator('#media-event').select_option(event);p.locator('#media-caption').fill('Release QA event photo');p.get_by_role('button',name='Save media',exact=True).click();p.wait_for_selector('#profile-media .record img');p.wait_for_function('()=>{const e=document.querySelector("#profile-media img");return e?.complete&&e.naturalWidth>0}');self.assertTrue(p.locator('#profile-media img').evaluate('(e)=>e.complete&&e.naturalWidth>0'))
  items=p.evaluate('async id=>(await import("/assets/media-library.js")).listMedia(id).then(xs=>xs.map(x=>({id:x.id,athleteId:x.athleteId,eventRef:x.eventRef})))',athlete);self.assertEqual(items[0]['eventRef'],event);self.assertEqual(items[0]['athleteId'],athlete)
  self.section('My Feed');p.wait_for_selector('#content-choices-news');self.assertEqual(p.locator('#my-feed .content-items article').count(),0);p.locator('#content-choices-news').evaluate('(e)=>e.open=true');p.locator('#content-choices-news input:not([disabled])').first.check();self.assertGreater(p.locator('#my-feed .content-items article').count(),0)
  self.section('Development');p.wait_for_selector('#content-choices-development');p.locator('#content-choices-development').evaluate('(e)=>e.open=true');p.locator('#content-choices-development input:not([disabled])').first.check();self.assertGreater(p.locator('#camps .content-items article').count(),0)
  self.section('Network');p.locator('#recommendations button[data-save]').first.click();self.assertEqual(len(self.state()['profiles'][0]['saved']),1);self.assertNotIn('recruiting',self.state()['profiles'][0]['modules'])
  p.goto(base.BASE+'/my-ap?scenario=local&section=calendar');p.wait_for_selector('#platform-calendar');p.get_by_label('Calendar date',exact=True).fill('2026-11-16');p.get_by_label('Calendar date',exact=True).press('Tab');p.get_by_role('button',name='Week',exact=True).click();p.wait_for_selector('#platform-calendar .ap-activity');self.assertIn('QA tournament',p.locator('#platform-calendar').inner_text());self.assertIn('Release moved practice',p.locator('#platform-calendar').inner_text());self.assertEqual(len(self.state()['profiles'][0]['plans']),2)
  p.screenshot(path=str(OUT/f'{base.ENGINE}-ipad-calendar.png'),full_page=True)
  p.goto(base.BASE+'/siem/setup');p.wait_for_selector('#siem-people');self.assertIn('Release QA Athlete',p.locator('#siem-people').inner_text());p.locator('.siem-local-tools').evaluate('(e)=>e.open=true');p.get_by_role('button',name='Save local permissions',exact=True).click();family=self.family();self.assertEqual(len([a for a in family['athletes'] if a['id']==athlete]),1);self.assertEqual(len([a for a in family['athletes'] if a['id']==parent]),1)
  p.goto(base.BASE+'/my-pathway?athlete='+athlete);p.wait_for_selector('#show-tryouts');p.get_by_text('About My Sport · Positions and Goals',exact=True).click();p.locator('#athlete-age').fill('16');p.get_by_role('button',name='Save details',exact=True).click();self.section('Recruiting');p.get_by_role('button',name='Open local recruiting planner',exact=True).click();p.get_by_text('Parent-controlled recruiting preview',exact=True).click();p.wait_for_selector('#recruiting-rules');self.assertTrue(p.get_by_role('button',name='Parent approve local preview').is_disabled());p.locator('#recruiting-rules').check();p.get_by_label('Include identity',exact=True).check();p.get_by_label('Include schedule',exact=True).check();p.get_by_label('Include stats',exact=True).check();p.get_by_role('button',name='Parent approve local preview',exact=True).click();self.assertIn('Release QA Athlete',p.locator('.recruiting-preview').inner_text());self.assertIn('Goals: 2',p.locator('.recruiting-preview').inner_text());p.get_by_role('button',name='Revoke preview approval',exact=True).click();self.assertFalse(self.state()['profiles'][0]['recruiting']['parentApproved'])
  # Module toggles may change only module fields, never saved identity/content/records.
  self.section('Profile');before=self.state()['profiles'][0];p.locator('#module-customizer').evaluate('(e)=>e.open=true')
  for module in ['recruiting','saved','teams','media']:
   box=p.locator('#choose-'+module)
   if box.is_checked():box.uncheck()
  after=self.state()['profiles'][0]
  for key in set(before)-{'modules','moduleVersion','mediaEnabled'}:self.assertEqual(after.get(key),before[key],key)
  self.assertNotIn('recruiting',after['modules']);self.assertEqual(p.evaluate('async id=>(await import("/assets/media-library.js")).listMedia(id).then(xs=>xs.length)',athlete),1)
  p.reload();p.wait_for_selector('#show-tryouts');self.assertEqual(self.state()['active'],athlete);self.assertEqual(len(self.state()['profiles']),1);self.assertEqual(self.state()['profiles'][0]['plans'],before['plans']);self.assertEqual(self.state()['profiles'][0]['records'],before['records'])
  for size,w,h in [('desktop',1440,900),('ipad',810,1080),('iphone',390,844)]:
   p.set_viewport_size({'width':w,'height':h});p.goto(base.BASE+'/my-pathway?view=family');p.wait_for_selector('.family-athlete-card');self.assertIn('Release QA Parent',p.locator('.profile-athlete-name').inner_text());self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'));p.screenshot(path=str(OUT/f'{base.ENGINE}-{size}-parent.png'),full_page=True);p.locator('.family-athlete-card').get_by_role('link',name='View Athlete').click();p.wait_for_selector('#show-tryouts');self.assertFalse(p.evaluate('document.documentElement.scrollWidth>innerWidth+1'));p.screenshot(path=str(OUT/f'{base.ENGINE}-{size}-athlete.png'),full_page=True)
  self.assertEqual(self.writes,[])
  (OUT/f'{base.ENGINE}-journey.json').write_text(json.dumps({'parentId':parent,'athleteId':athlete,'seriesId':sid,'eventRef':event,'media':items,'profileCount':len(self.state()['profiles']),'externalWrites':self.writes},indent=2))
 def test_02_siem_without_profile_lockedin_off_and_independent_research(self):
  p=self.page;p.goto(base.BASE+'/siem/setup');self.assertEqual(p.get_by_role('heading',name='Four pillars. Your permissions.',exact=True,include_hidden=True).count(),1);p.locator('#siem-participant-add input[name=nickname]').fill('Lightweight SIEM participant');p.locator('#siem-participant-add select[name=sport]').select_option('swimming');p.get_by_role('button',name='Add lightweight athlete',exact=True).click();p.wait_for_function('()=>JSON.parse(localStorage.getItem("arenaPathway.siem.v1")).athletes.length===1');athlete=self.family()['athletes'][0]['id'];self.assertEqual(self.family()['athletes'][0]['origin'],'siem');self.assertFalse(self.family()['permissions']['recruiting']);self.assertFalse(self.family()['permissions']['lockedIn']);self.assertEqual(p.evaluate('JSON.parse(localStorage.getItem("arenaPathway.v2")||"null")?.profiles?.length||0'),0)
  p.locator('.siem-local-tools').evaluate('(e)=>e.open=true');p.locator('#siem-event').evaluate('(e)=>e.closest("details").open=true');f=p.locator('#siem-event');f.locator('[name=athleteId]').select_option(athlete);f.locator('[name=title]').fill('Standalone SIEM practice');f.locator('[name=ref]').fill('rc-standalone');f.locator('[name=start]').fill('2026-11-16T17:00');f.locator('[name=end]').fill('2026-11-16T18:00');f.get_by_role('button',name='Save local event',exact=True).click();self.assertEqual(len(self.family()['events']),1);self.assertEqual(self.family()['events'][0]['athleteId'],athlete)
  p.goto(base.BASE+'/recruiting');p.wait_for_selector('[aria-label="Recruiting research"]');self.assertEqual(p.evaluate('JSON.parse(localStorage.getItem("arenaPathway.v2")||"null")?.profiles?.length||0'),0);self.assertEqual(len(self.family()['events']),1);self.assertFalse(self.family()['permissions']['lockedIn']);self.assertEqual(self.writes,[])
if __name__=='__main__':unittest.main(verbosity=2)
